static int write_bundle_refs(int bundle_fd, struct rev_info *revs)
{
	for (i = 0; i < revs->pending.nr; i++) {
		struct object_array_entry *e = revs->pending.objects + i;
		if (e->item->flags & UNINTERESTING)
			continue;
		if (repo_dwim_ref(the_repository, e->name, strlen(e->name),
				  &oid, &ref, 0) != 1)
			goto skip_write_ref;
		if (refs_read_ref_full(get_main_ref_store(the_repository), e->name, RESOLVE_REF_READING, &oid, &flag))
			flag = 0;
		display_ref = (flag & REF_ISSYMREF) ? e->name : ref;
		if (e->item->type == OBJ_TAG &&
				!is_tag_in_date_range(e->item, revs)) {
			e->item->flags |= UNINTERESTING;
		}
		if (!(e->item->flags & SHOWN) && e->item->type == OBJ_COMMIT) {
			warning(_("ref '%s' is excluded by the rev-list options"),
		}
		if (!oideq(&oid, &e->item->oid)) {
			struct commit *one = lookup_commit_reference(revs->repo, &oid);  // The line where the warning is located
			if (e->item == &(one->object)) {
				obj = parse_object_or_die(&oid, e->name);
				obj->flags |= SHOWN;
				add_pending_object(revs, obj, e->name);
			}
		}
		ref_count++;
		write_or_die(bundle_fd, oid_to_hex(&e->item->oid), the_hash_algo->hexsz);
		write_or_die(bundle_fd, " ", 1);
		write_or_die(bundle_fd, display_ref, strlen(display_ref));
		write_or_die(bundle_fd, "\n", 1);
		free(ref);
	}
	write_or_die(bundle_fd, "\n", 1);
	return ref_count;

static int update_one(struct cache_tree *it,
		      struct cache_entry **cache,
		      int entries,
		      const char *base,
		      int baselen,
		      int *skip_count,
		      int flags)
{
	if (entries > 0) {
		const struct cache_entry *ce = cache[0];
		if (S_ISSPARSEDIR(ce->ce_mode) &&
		    ce->ce_namelen == baselen &&
		    !strncmp(ce->name, base, baselen)) {
		}
	}
	if (0 <= it->entry_count && repo_has_object_file(the_repository, &it->oid))
		return it->entry_count;
	for (i = 0; i < it->subtree_nr; i++)
		it->down[i]->used = 0;
	i = 0;
	while (i < entries) {
		const struct cache_entry *ce = cache[i];
		path = ce->name;
		pathlen = ce_namelen(ce);
		if (pathlen <= baselen || memcmp(base, path, baselen))
			break; /* at the end of this level */
		slash = strchr(path + baselen, '/');
		if (!slash) {
			i++;
		}
		sublen = slash - (path + baselen);
		sub = find_subtree(it, path + baselen, sublen, 1);  // The line where the warning is located
		if (!sub->cache_tree)
			sub->cache_tree = cache_tree();
		subcnt = update_one(sub->cache_tree,
				    cache + i, entries - i,
				    baselen + sublen + 1,
		if (subcnt < 0)
			return subcnt;
		if (!subcnt)
			die("index cache-tree records empty sub-tree");
		i += subcnt;
		sub->count = subcnt; /* to be used in the next loop */
		*skip_count += subskip;
		sub->used = 1;
	}
	discard_unused_subtrees(it);
	while (i < entries) {
		if (slash) {
			sub = find_subtree(it, path + baselen, entlen, 0);
			if (!sub)
				die("cache-tree.c: '%.*s' in '%s' not found",
				    entlen, path + baselen, path);
			i += sub->count;
		}
		else {
		}
		if (is_null_oid(oid) ||
		    (!ce_missing_ok && !repo_has_object_file(the_repository, oid))) {
			strbuf_release(&buffer);
			return error("invalid object %06o %s for '%.*s'",
				mode, oid_to_hex(oid), entlen+baselen, path);
		}
		if (ce->ce_flags & CE_REMOVE) {
			*skip_count = *skip_count + 1;
		}
		if (!sub && ce_intent_to_add(ce)) {
			to_invalidate = 1;
		}
		if (contains_ita && is_empty_tree_oid(oid, the_repository->hash_algo))
			continue;
		strbuf_grow(&buffer, entlen + 100);
		strbuf_addf(&buffer, "%o %.*s%c", mode, entlen, path + baselen, '\0');
		strbuf_add(&buffer, oid->hash, the_hash_algo->rawsz);
	}
	if (repair) {
		hash_object_file(the_hash_algo, buffer.buf, buffer.len,
		if (repo_has_object_file_with_flags(the_repository, &oid, OBJECT_INFO_SKIP_FETCH_OBJECT))
			oidcpy(&it->oid, &oid);
		else
			to_invalidate = 1;
	} else if (dryrun) {
		hash_object_file(the_hash_algo, buffer.buf, buffer.len,
	} else if (write_object_file_flags(buffer.buf, buffer.len, OBJ_TREE,
					   &it->oid, NULL, flags & WRITE_TREE_SILENT
		strbuf_release(&buffer);
		return -1;
	}
	strbuf_release(&buffer);
	it->entry_count = to_invalidate ? -1 : i - *skip_count;
	return i;

