void ahead_behind(struct repository *r,
		  struct commit **commits, size_t commits_nr,
		  struct ahead_behind_count *counts, size_t counts_nr)
{
	struct prio_queue queue = { .compare = compare_commits_by_gen_then_commit_date };
	size_t width = DIV_ROUND_UP(commits_nr, BITS_IN_EWORD);
	if (!commits_nr || !counts_nr)
		return;
	ensure_generations_valid(r, commits, commits_nr);
	for (size_t i = 0; i < commits_nr; i++) {
		struct commit *c = commits[i];
		struct bitmap *bitmap = get_bit_array(c, width);
		bitmap_set(bitmap, i);
		insert_no_dup(&queue, c);
	}
	while (queue_has_nonstale(&queue)) {
		struct commit *c = prio_queue_get(&queue);  // The line where the warning is located
		struct bitmap *bitmap_c = get_bit_array(c, width);
		for (size_t i = 0; i < counts_nr; i++) {
			int reach_from_tip = !!bitmap_get(bitmap_c, counts[i].tip_index);
			int reach_from_base = !!bitmap_get(bitmap_c, counts[i].base_index);
			if (reach_from_tip ^ reach_from_base) {
				if (reach_from_base)
					counts[i].behind++;
				else
					counts[i].ahead++;
			}
		}
		for (p = c->parents; p; p = p->next) {
			repo_parse_commit(r, p->item);
			bitmap_p = get_bit_array(p->item, width);
			bitmap_or(bitmap_p, bitmap_c);
			if (bitmap_popcount(bitmap_p) == commits_nr)
				p->item->object.flags |= STALE;
			insert_no_dup(&queue, p->item);
		}
		free_bit_array(c);
	}
	repo_clear_commit_marks(r, PARENT2 | STALE);
	clear_prio_queue(&queue);

static int verify_one_commit_graph(struct repository *r,
				   struct commit_graph *g,
				   struct progress *progress,
				   uint64_t *seen)
{
	uint32_t i, cur_fanout_pos = 0;
	if (!commit_graph_checksum_valid(g)) {
		verify_commit_graph_error = VERIFY_COMMIT_GRAPH_ERROR_HASH;
	}
	for (i = 0; i < g->num_commits; i++) {
		oidread(&cur_oid, g->chunk_oid_lookup + st_mult(g->hash_len, i));
		if (i && oidcmp(&prev_oid, &cur_oid) >= 0)
			graph_report(_("commit-graph has incorrect OID order: %s then %s"),
				     oid_to_hex(&prev_oid),
				     oid_to_hex(&cur_oid));
		oidcpy(&prev_oid, &cur_oid);
		while (cur_oid.hash[0] > cur_fanout_pos) {
			if (i != fanout_value)
				graph_report(_("commit-graph has incorrect fanout value: fanout[%d] = %u != %u"),
					     cur_fanout_pos, fanout_value, i);
		}
		graph_commit = lookup_commit(r, &cur_oid);
		if (!parse_commit_in_graph_one(r, g, graph_commit))
			graph_report(_("failed to parse commit %s from commit-graph"),
				     oid_to_hex(&cur_oid));
	}
	while (cur_fanout_pos < 256) {
		uint32_t fanout_value = get_be32(g->chunk_oid_fanout + cur_fanout_pos);
		if (g->num_commits != fanout_value)
			graph_report(_("commit-graph has incorrect fanout value: fanout[%d] = %u != %u"),
				     cur_fanout_pos, fanout_value, i);
		cur_fanout_pos++;
	}
	if (verify_commit_graph_error & ~VERIFY_COMMIT_GRAPH_ERROR_HASH)
		return verify_commit_graph_error;
	for (i = 0; i < g->num_commits; i++) {
		timestamp_t max_generation = 0;
		display_progress(progress, ++(*seen));
		oidread(&cur_oid, g->chunk_oid_lookup + st_mult(g->hash_len, i));
		graph_commit = lookup_commit(r, &cur_oid);  // The line where the warning is located
		odb_commit = (struct commit *)create_object(r, &cur_oid, alloc_commit_node(r));
		if (repo_parse_commit_internal(r, odb_commit, 0, 0)) {
			graph_report(_("failed to parse commit %s from object database for commit-graph"),
				     oid_to_hex(&cur_oid));
		}
		if (!oideq(&get_commit_tree_in_graph_one(r, g, graph_commit)->object.oid,
			   get_commit_tree_oid(odb_commit)))
			graph_report(_("root tree OID for commit %s in commit-graph is %s != %s"),
				     oid_to_hex(&cur_oid),
				     oid_to_hex(get_commit_tree_oid(graph_commit)),
				     oid_to_hex(get_commit_tree_oid(odb_commit)));
		graph_parents = graph_commit->parents;
		odb_parents = odb_commit->parents;
		while (graph_parents) {
			if (!odb_parents) {
				graph_report(_("commit-graph parent list for commit %s is too long"),
					     oid_to_hex(&cur_oid));
			}
			parse_commit_in_graph_one(r, g, graph_parents->item);
			if (!oideq(&graph_parents->item->object.oid, &odb_parents->item->object.oid))
				graph_report(_("commit-graph parent for %s is %s != %s"),
					     oid_to_hex(&cur_oid),
					     oid_to_hex(&graph_parents->item->object.oid),
					     oid_to_hex(&odb_parents->item->object.oid));
			generation = commit_graph_generation_from_graph(graph_parents->item);
			if (generation > max_generation)
				max_generation = generation;
			graph_parents = graph_parents->next;
			odb_parents = odb_parents->next;
		}
		if (odb_parents)
			graph_report(_("commit-graph parent list for commit %s terminates early"),
				     oid_to_hex(&cur_oid));
		if (commit_graph_generation_from_graph(graph_commit))
			seen_gen_non_zero = graph_commit;
		else
			seen_gen_zero = graph_commit;
		if (seen_gen_zero)
			continue;
		if (!g->read_generation_data && max_generation == GENERATION_NUMBER_V1_MAX)
			max_generation--;
		generation = commit_graph_generation(graph_commit);
	}
	if (seen_gen_zero && seen_gen_non_zero)
		graph_report(_("commit-graph has both zero and non-zero "
			     oid_to_hex(&seen_gen_zero->object.oid),
			     oid_to_hex(&seen_gen_non_zero->object.oid));

static struct commit_list *paint_down_to_common(struct repository *r,
						struct commit *one, int n,
						struct commit **twos,
						timestamp_t min_generation)
{
	struct prio_queue queue = { compare_commits_by_gen_then_commit_date };
	if (!min_generation && !corrected_commit_dates_enabled(r))
		queue.compare = compare_commits_by_commit_date;
	if (!n) {
	}
	prio_queue_put(&queue, one);
	for (i = 0; i < n; i++) {
		prio_queue_put(&queue, twos[i]);
	}
	while (queue_has_nonstale(&queue)) {
		struct commit *commit = prio_queue_get(&queue);  // The line where the warning is located
		timestamp_t generation = commit_graph_generation(commit);
		last_gen = generation;
		if (generation < min_generation)
			break;
		flags = commit->object.flags & (PARENT1 | PARENT2 | STALE);
		if (flags == (PARENT1 | PARENT2)) {
			if (!(commit->object.flags & RESULT)) {
				commit_list_insert_by_date(commit, &result);
			}
			flags |= STALE;
		}
		parents = commit->parents;
		while (parents) {
			struct commit *p = parents->item;
			parents = parents->next;
			if ((p->object.flags & flags) == flags)
				continue;
			if (repo_parse_commit(r, p))
				return NULL;
			prio_queue_put(&queue, p);
		}
	}
	clear_prio_queue(&queue);
	return result;

