    void
ex_sort(exarg_T *eap)
{
    long	maxlen = 0;
    size_t	count = (size_t)(eap->line2 - eap->line1 + 1);
    int		unique = FALSE;
    int		sort_what = 0;
    int		format_found = 0;
    if (count <= 1)
	return;
    if (u_save((linenr_T)(eap->line1 - 1), (linenr_T)(eap->line2 + 1)) == FAIL)
	return;
    regmatch.regprog = NULL;
    nrs = ALLOC_MULT(sorti_T, count);
    if (nrs == NULL)
	goto sortend;
    sort_flt = 0;
    for (p = eap->arg; *p != NUL; ++p)
    {
	if (VIM_ISWHITE(*p))
	    ;
	else if (*p == 'i')
	else if (*p == 'l')
	else if (*p == 'r')
	else if (*p == 'n')
	    ++format_found;
	else if (*p == 'f')
	    sort_flt = 1;
	    ++format_found;
	else if (*p == 'b')
	    sort_what = STR2NR_BIN + STR2NR_FORCE;
	    ++format_found;
	else if (*p == 'o')
	    sort_what = STR2NR_OCT + STR2NR_FORCE;
	    ++format_found;
	else if (*p == 'x')
	    sort_what = STR2NR_HEX + STR2NR_FORCE;
	    ++format_found;
	else if (*p == 'u')
	    unique = TRUE;
	else if (*p == '"')	// comment start
	else if (eap->nextcmd == NULL && check_nextcmd(p) != NULL)
	else if (!ASCII_ISALPHA(*p) && regmatch.regprog == NULL)
	    s = skip_regexp_err(p + 1, *p, TRUE);
	    if (s == NULL)
	    *s = NUL;
	    if (s == p + 1)
		if (last_search_pat() == NULL)
		regmatch.regprog = vim_regcomp(last_search_pat(), RE_MAGIC);
		regmatch.regprog = vim_regcomp(p + 1, RE_MAGIC);
	    if (regmatch.regprog == NULL)
	    regmatch.rm_ic = p_ic;
	}
    }
    if (format_found > 1)
    {
    }
    sort_nr += sort_what;
    for (lnum = eap->line1; lnum <= eap->line2; ++lnum)
    {
	s = ml_get(lnum);
	if (maxlen < len)
	    maxlen = len;
	if (regmatch.regprog != NULL && vim_regexec(&regmatch, s, 0))
	{
	}
	else
	    if (regmatch.regprog != NULL)
		end_col = 0;
	if (sort_nr || sort_flt)
	{
	    p = s + start_col;
	    if (sort_nr)
	    {
		if (sort_what & STR2NR_HEX)
		    s = skiptohex(p);
		else if (sort_what & STR2NR_BIN)
		    s = skiptobin(p);
		    s = skiptodigit(p);
		if (s > p && s[-1] == '-')
		    --s;  // include preceding negative sign
		if (*s == NUL)
		{
		}
		else
		    vim_str2nr(s, NULL, NULL, sort_what,
		}
	    }
	    else
		s = skipwhite(p);
		if (*s == '+')
		    s = skipwhite(s + 1);
		if (*s == NUL)
						      strtod((char *)s, NULL);
	    }
	}
	else
	}
	nrs[lnum - eap->line1].lnum = lnum;
	if (regmatch.regprog != NULL)
	    fast_breakcheck();
	if (got_int)
	    goto sortend;
    }
    sortbuf1 = alloc(maxlen + 1);
    if (sortbuf1 == NULL)
	goto sortend;
    if (sortbuf2 == NULL)
	goto sortend;
    qsort((void *)nrs, count, sizeof(sorti_T), sort_compare);
    if (sort_abort)
	goto sortend;
    lnum = eap->line2;
    for (i = 0; i < count; ++i)
    {
	linenr_T get_lnum = nrs[eap->forceit ? count - i - 1 : i].lnum;
	if (get_lnum + ((linenr_T)count - 1) != lnum)
	    change_occurred = TRUE;
	s = ml_get(get_lnum);
	if (!unique || i == 0 || string_compare(s, sortbuf1) != 0)
	{
	    STRCPY(sortbuf1, s);  // The line where the warning is located
	    if (ml_append(lnum++, sortbuf1, (colnr_T)0, FALSE) == FAIL)
		break;
	}
	fast_breakcheck();
	if (got_int)
	    goto sortend;
    }
    if (i == count)
	for (i = 0; i < count; ++i)
	    ml_delete(eap->line1);
    else
	count = 0;
    deleted = (long)(count - (lnum - eap->line2));
    if (deleted > 0)
    {
	mark_adjust(eap->line2 - deleted, eap->line2, (long)MAXLNUM, -deleted);
	msgmore(-deleted);
    }
    else if (deleted < 0)
	mark_adjust(eap->line2, MAXLNUM, -deleted, 0L);
    if (change_occurred || deleted != 0)
	changed_lines(eap->line1, 0, eap->line2 + 1, -deleted);
    curwin->w_cursor.lnum = eap->line1;
    beginline(BL_WHITE | BL_FIX);
    vim_free(sortbuf1);

    if (result == NULL)
	return NULL;
    for (p = result; *p; )
    {
	if (STRNCMP(p, "<sfile>", 7) != 0)
	    ++p;
	else
	    repl = eval_vars(p, result, &srclen, NULL, &errormsg, NULL, TRUE);
	    if (errormsg != NULL)
	    if (repl == NULL)		// no match (cannot happen)
	    repllen = STRLEN(repl);
	    resultlen += repllen - srclen;
	    newres = alloc(resultlen + 1);
	    if (newres == NULL)
	    len = p - result;
	    mch_memmove(newres, result, len);
	    STRCPY(newres + len, repl);  // The line where the warning is located
	    vim_free(repl);
	    result = newres;
	}
    }

    static char_u *
repl_cmdline(
    exarg_T	*eap,
    char_u	*src,
    size_t	srclen,
    char_u	*repl,
    char_u	**cmdlinep)
{
    repllen = STRLEN(repl);
    taillen = STRLEN(src + srclen);
    i = (src - *cmdlinep) + repllen + taillen + 3;
    if (eap->nextcmd != NULL)
	i += STRLEN(eap->nextcmd);	// add space for next command
    if ((new_cmdline = alloc(i)) == NULL)
	return NULL;			// out of memory!
    new_cmdlinelen = src - *cmdlinep;	// length of part before replacement
    mch_memmove(new_cmdline, *cmdlinep, new_cmdlinelen);
    mch_memmove(new_cmdline + new_cmdlinelen, repl, repllen);
    new_cmdlinelen += repllen;		// remember the end of the string
    STRCPY(new_cmdline + new_cmdlinelen, src + srclen);  // The line where the warning is located

    static char_u *
repl_cmdline(
    exarg_T	*eap,
    char_u	*src,
    size_t	srclen,
    char_u	*repl,
    char_u	**cmdlinep)
{
    repllen = STRLEN(repl);
    taillen = STRLEN(src + srclen);
    i = (src - *cmdlinep) + repllen + taillen + 3;
    if (eap->nextcmd != NULL)
	i += STRLEN(eap->nextcmd);	// add space for next command
    if ((new_cmdline = alloc(i)) == NULL)
	return NULL;			// out of memory!
    new_cmdlinelen = src - *cmdlinep;	// length of part before replacement
    mch_memmove(new_cmdline, *cmdlinep, new_cmdlinelen);
    mch_memmove(new_cmdline + new_cmdlinelen, repl, repllen);
    new_cmdlinelen += repllen;		// remember the end of the string
    if (eap->nextcmd != NULL)		// append next command
    {
	new_cmdlinelen += taillen + 1;
	STRCPY(new_cmdline + new_cmdlinelen, eap->nextcmd);  // The line where the warning is located
    }

static int	if_level = 0;		// depth in :if
    static char_u *
do_one_cmd(
    char_u	**cmdlinep,
    int		flags,
#ifdef FEAT_EVAL
    cstack_T	*cstack,
#endif
