    }
    ni = (!IS_USER_CMDIDX(ea.cmdidx)
    if (ea.cmdidx == CMD_if)
    if (if_level)
    if (*p == '!' && ea.cmdidx != CMD_substitute
	    && ea.cmdidx != CMD_smagic && ea.cmdidx != CMD_snomagic)
    {
	++p;
