    if ((ea.argt & EX_DFLALL) && ea.addr_count == 0)
	address_default_all(&ea);
    if (       (ea.argt & EX_REGSTR)
	    && *ea.arg != NUL
	    && (!IS_USER_CMDIDX(ea.cmdidx) || *ea.arg != '=')
