    static char_u *
regatom(int *flagp)
{
    switch (c)
    {
	    switch (c)
			      ret = NULL;
			      while ((c = getchr()) != ']')
				  if (ret == NULL)
				      ret = br;
				      if (reg_toolong)
				  lastnode = regatom(flagp);
				  if (lastnode == NULL)
			      br = regnode(NOTHING);  // The line where the warning is located
				  regtail(lastnode, br);
				  regtail(lastbranch, br);
				  for (br = ret; br != lastnode; )
				      if (OP(br) == BRANCH)
					  regtail(br, lastbranch);
					  if (reg_toolong)
					  br = OPERAND(br);
					  br = regnext(br);
			      *flagp &= ~(HASWIDTH | SIMPLE);
    }
    return ret;

    static char_u *
regatom(int *flagp)
{
    switch (c)
    {
			      char_u	*lastnode = NULL;
			      while ((c = getchr()) != ']')
				  if (lastnode == NULL)
			      if (ret == NULL)
			      br = regnode(NOTHING);
			      if (ret != JUST_CALC_SIZE)
				  regtail(lastnode, br);
				  for (br = ret; br != lastnode; )
				      if (OP(br) == BRANCH)
					  regtail(br, lastbranch);
					  if (reg_toolong)
					      return NULL;
					  br = OPERAND(br);
					  br = regnext(br);  // The line where the warning is located
			      *flagp &= ~(HASWIDTH | SIMPLE);
    }
    return ret;

