    char_u *
transstr(char_u *s)
{
    if (has_mbyte)
    {
	len = 0;
	p = s;
	while (*p != NUL)
	{
	    if ((l = (*mb_ptr2len)(p)) > 1)
	    {
		p += l;
		if (vim_isprintc(c))
		    len += l;
		else
		    len += (int)STRLEN(hexbuf);
		}
	    }
	    else
		l = byte2cells(*p++);
		if (l > 0)
		    len += l;
		    len += 4;	// illegal byte sequence
	    }
	}
	res = alloc(len + 1);
    }
    else
	res = alloc(vim_strsize(s) + 1);
    if (res == NULL)
	return NULL;
    *res = NUL;
    p = s;
    while (*p != NUL)
    {
	if (has_mbyte && (l = (*mb_ptr2len)(p)) > 1)
	{
	    c = (*mb_ptr2char)(p);
	    if (vim_isprintc(c))
		STRNCAT(res, p, l);	// append printable multi-byte char
	    else
		transchar_hex(res + STRLEN(res), c);
	    p += l;
	}
	else
	    STRCAT(res, transchar_byte(*p++));  // The line where the warning is located
    }
    return res;

    void
globpath(
    char_u	*path,
    char_u	*file,
    garray_T	*ga,
    int		expand_options,
    int		dirs)
{
    buf = alloc(MAXPATHL);
    if (buf == NULL)
	return;
    ExpandInit(&xpc);
    xpc.xp_context = dirs ? EXPAND_DIRECTORIES : EXPAND_FILES;
    filelen = STRLEN(file);
    while (*path != NUL)
    {
	pathlen = (size_t)copy_option_part(&path, buf, MAXPATHL, ",");
	seplen = (*buf != NUL && !after_pathsep(buf, buf + pathlen))
	    ? STRLEN_LITERAL(TMP_PATHSEPSTR)
	if (pathlen + seplen + filelen + 1 <= MAXPATHL)
	{
	    if (seplen > 0)
	    {
		pathlen += seplen;
	    }
	    STRCPY(buf + pathlen, file);  // The line where the warning is located
	    if (ExpandFromContext(&xpc, buf, &p, &num_p,
			     WILD_SILENT|expand_options) != FAIL && num_p > 0)
	    {
		ExpandEscape(&xpc, buf, num_p, p, WILD_SILENT|expand_options);
		if (ga_grow(ga, num_p) == OK)
		{
		    for (int i = 0; i < num_p; ++i)
		    {
			++ga->ga_len;
		    }
		}
		vim_free(p);
	    }
	}
    }

