	if (path == NULL)
	    path = (char_u *)"";
    }
    ga_init2(&ga, sizeof(char *), 10);
    hash_init(&found_ht);
    for (s = path; ; s = e)
    {
	if (*s == NUL)
	{
	    if (did_curdir)
		break;
	    flags |= EW_DIR;
	    e = s;
	    pathlen = 0;
	    seplen = 0;
	}
	else
	    e = vim_strchr(s, ':');
	    if (e == NULL)
		e = s + STRLEN(s);
	    pathlen = (size_t)(e - s);
	    if (STRNCMP(s, ".", pathlen) == 0)
		flags |= EW_DIR;
		flags &= ~EW_DIR;
	    seplen = !after_pathsep(s, e) ? STRLEN_LITERAL(PATHSEPSTR) : 0;
	}
	if (pathlen + seplen + patlen + 1 <= MAXPATHL)
	{
	    if (pathlen > 0)
	    {
		vim_strncpy(buf, s, pathlen);
		if (seplen > 0)
		{
		    STRCPY(buf + pathlen, PATHSEPSTR);
		    pathlen += seplen;
		}
	    }
	    STRCPY(buf + pathlen, pat);  // The line where the warning is located
	    expand_shellcmd_onedir(buf, pathlen, matches, numMatches, flags,
	}
	if (*e != NUL)
	    ++e;
    }
    vim_free(pat);

    static void
win_redr_status_matches(
    expand_T	*xp,
    int		num_matches,
    char_u	**matches,	// list of matches
    int		match,
    int		showtail)
{
    if (matches == NULL)	// interrupted completion?
	return;
    if (has_mbyte)
	buf = alloc(Columns * MB_MAXBYTES + 1);
    else
	buf = alloc(Columns + 1);
    if (buf == NULL)
	return;
    clen = status_match_len(xp, SHOW_MATCH(match)) + 3;
    if (match == 0)
	first_match = 0;
    else if (match < first_match)
	first_match = match;
	for (i = first_match; i < match; ++i)
	    clen += status_match_len(xp, SHOW_MATCH(i)) + 2;
	if (first_match > 0)
	    clen += 2;
	if ((long)clen > Columns)
	    first_match = match;
	    for (i = match; i < num_matches; ++i)
		clen += status_match_len(xp, SHOW_MATCH(i)) + 2;
		if ((long)clen >= Columns)
	    if (i == num_matches)
    }
    if (add_left)
	while (first_match > 0)
	    clen += status_match_len(xp, SHOW_MATCH(first_match - 1)) + 2;
	    if ((long)clen >= Columns)
	    --first_match;
	}
    if (first_match == 0)
    {
	*buf = NUL;
	len = 0;
    }
    else
	STRCPY(buf, "< ");
	len = 2;
    }
    clen = len;
    while ((long)(clen + status_match_len(xp, SHOW_MATCH(i)) + 2) < Columns)
    {
	if (i == match)
	{
	    selstart_col = clen;
	}
	for ( ; *s != NUL; ++s)
	{
	    s += skip_status_match_char(xp, s);
	    clen += ptr2cells(s);
	    if (has_mbyte && (l = (*mb_ptr2len)(s)) > 1)
	    {
		STRNCPY(buf + len, s, l);
		s += l - 1;
		len += l;
	    }
	    else
		STRCPY(buf + len, transchar_byte(*s));  // The line where the warning is located
		len += (int)STRLEN(buf + len);
	    }
	}
	if (i == match)
	    selend = buf + len;
	*(buf + len++) = ' ';
	*(buf + len++) = ' ';
	clen += 2;
	if (++i == num_matches)
		break;
    }
    if (i != num_matches)
    {
	++clen;
    }
    buf[len] = NUL;
    if (row >= 0)
    {
	screen_puts(buf, row, 0, attr);
	if (selstart != NULL && highlight)
	{
	    *selend = NUL;
	    screen_puts(selstart, row, selstart_col, HL_ATTR(HLF_WM));
	}
	screen_fill(row, row + 1, clen, (int)Columns, fillchar, fillchar, attr);
    }
    vim_free(buf);

    char_u *
do_string_sub(
    char_u	*str,
    size_t	len,
    char_u	*pat,
    char_u	*sub,
    typval_T	*expr,
    char_u	*flags,
    size_t	*ret_len)		// length of returned buffer
{
    ga_init2(&ga, 1, 200);
    regmatch.rm_ic = p_ic;
    regmatch.regprog = vim_regcomp(pat, RE_MAGIC + RE_STRING);
    if (regmatch.regprog != NULL)
    {
	char_u	*tail = str;
	char_u	*end = str + len;
	int	do_all = (flags[0] == 'g');
	char_u	*zero_width = NULL;
	while (vim_regexec_nl(&regmatch, str, (colnr_T)(tail - str)))
	{
	    if (regmatch.startp[0] == regmatch.endp[0])
	    {
		if (zero_width == regmatch.startp[0])
		{
		    i = mb_ptr2len(tail);
		    mch_memmove((char_u *)ga.ga_data + ga.ga_len, tail,
		    ga.ga_len += i;
		    tail += i;
		}
		zero_width = regmatch.startp[0];
	    }
	    sublen = vim_regsub(&regmatch, sub, expr, tail, 0, REGSUB_MAGIC);
	    if (sublen <= 0)
	    {
	    }
	    if (ga_grow(&ga, (int)((end - tail) + sublen -
			    (regmatch.endp[0] - regmatch.startp[0]))) == FAIL)
	    {
	    }
	    i = (int)(regmatch.startp[0] - tail);
	    (void)vim_regsub(&regmatch, sub, expr,
				  REGSUB_COPY | REGSUB_MAGIC);
	    ga.ga_len += i + sublen - 1;
	    tail = regmatch.endp[0];
	    if (*tail == NUL)
		break;
	    if (!do_all)
		break;
	}
	if (ga.ga_data != NULL)
	{
	    STRCPY((char *)ga.ga_data + ga.ga_len, tail);  // The line where the warning is located
	    ga.ga_len += (int)(end - tail);
	}
    }
    if (ga.ga_data != NULL)
    {
	len = (size_t)ga.ga_len;
    }
    ret = vim_strnsave(str, len);
    ga_clear(&ga);

