    if (eap->nextcmd != NULL)
	i += STRLEN(eap->nextcmd);	// add space for next command
    if ((new_cmdline = alloc(i)) == NULL)
	return NULL;			// out of memory!
    new_cmdlinelen = src - *cmdlinep;	// length of part before replacement
    mch_memmove(new_cmdline, *cmdlinep, new_cmdlinelen);
    mch_memmove(new_cmdline + new_cmdlinelen, repl, repllen);
    new_cmdlinelen += repllen;		// remember the end of the string
    if (eap->nextcmd != NULL)		// append next command
    {
	new_cmdlinelen += taillen + 1;
	STRCPY(new_cmdline + new_cmdlinelen, eap->nextcmd);  // The line where the warning is located
    }

    p = alloc(STRLEN(*pp) + 2);
    if (p == NULL)
	return;
    p[0] = '\\';
    STRCPY(p + 1, *pp);  // The line where the warning is located
    vim_free(*pp);

    static int
cmdline_browse_history(
	int	c,
	int	firstc,
	char_u	**curcmdstr,
	size_t	*curcmdstrlen,
	int	histype,
	int	*hiscnt_p,
	expand_T *xp)
{
    int		hiscnt = orig_hiscnt = *hiscnt_p;
    char_u	*lookfor = *curcmdstr;
    size_t	lookforlen = *curcmdstrlen;
    if (get_hislen() == 0 || firstc == NUL)	// no history
	return CMDLINE_NOT_CHANGED;
    if (lookfor == NULL)
    {
	if ((lookfor = vim_strnsave(ccline.cmdbuff, ccline.cmdlen)) == NULL)
	    return CMDLINE_NOT_CHANGED;
	lookfor[ccline.cmdpos] = NUL;
	lookforlen = ccline.cmdpos;
    }
    for (;;)
    {
	if (c == K_UP || c == K_S_UP || c == Ctrl_P
		|| c == K_PAGEUP || c == K_KPAGEUP)
	{
	    if (hiscnt == get_hislen())	// first time
		hiscnt = *get_hisidx(histype);
	    else if (hiscnt == 0 && *get_hisidx(histype)
		hiscnt = get_hislen() - 1;
	    else if (hiscnt != *get_hisidx(histype) + 1)
		--hiscnt;
		hiscnt = orig_hiscnt;
	    }
	}
	else    // one step forwards
	    if (hiscnt == *get_hisidx(histype))
		hiscnt = get_hislen();
	    if (hiscnt == get_hislen())
		hiscnt = 0;
		++hiscnt;
	}
	if (hiscnt < 0 || get_histentry(histype)[hiscnt].hisstr
		== NULL)
	{
	    hiscnt = orig_hiscnt;
	}
	if ((c != K_UP && c != K_DOWN)
		|| hiscnt == orig_hiscnt
		|| STRNCMP(get_histentry(histype)[hiscnt].hisstr,
		    lookfor, lookforlen) == 0)
	    break;
    }
    if (hiscnt != orig_hiscnt)	// jumped to other entry
    {
	if (hiscnt == get_hislen())
	{
	    p = lookfor;	// back to the old one
	}
	else
	    p = get_histentry(histype)[hiscnt].hisstr;
	    plen = get_histentry(histype)[hiscnt].hisstrlen;
	}
	if (histype == HIST_SEARCH
		&& p != lookfor
		&& (old_firstc = p[plen + 1]) != firstc)
	{
	}
	else
	    if (ccline.cmdbuff == NULL)
	    STRCPY(ccline.cmdbuff, p);  // The line where the warning is located
	}
    }

static int	if_level = 0;		// depth in :if
    static char_u *
do_one_cmd(
    char_u	**cmdlinep,
    int		flags,
#ifdef FEAT_EVAL
    cstack_T	*cstack,
#endif
    char_u	*(*fgetline)(int, void *, int, getline_opt_T),
    void	*cookie)		// argument for fgetline()
{
    char	*errormsg = NULL;	// error message
    int		starts_with_colon = FALSE;
    int		sourcing = flags & DOCMD_VERBOSE;
    int		did_append_cmd = FALSE;
    CLEAR_FIELD(ea);
    ea.line1 = 1;
    ea.line2 = 1;
    if (quitmore
	    && !getline_equal(fgetline, cookie, getnextac))
	--quitmore;
    if ((*cmdlinep)[0] == '#' && (*cmdlinep)[1] == '!')
	goto doend;
    ea.cmd = *cmdlinep;
    ea.cmdlinep = cmdlinep;
    ea.ea_getline = fgetline;
    ea.cookie = cookie;
    if (parse_command_modifiers(&ea, &errormsg, &cmdmod, FALSE) == FAIL)
	goto doend;
    after_modifier = ea.cmd;
    ea.skip = (if_level > 0);
    cmd = ea.cmd;
    int vim9script = in_vim9script();
    if (vim9script && (flags & DOCMD_RANGEOK) == 0)
    {
	may_have_range = FALSE;
	for (p = ea.cmd; p >= *cmdlinep; --p)
	{
	    if (*p == ':')
		may_have_range = TRUE;
	    if (p < ea.cmd && !VIM_ISWHITE(*p))
		break;
	}
    }
    else
	may_have_range = TRUE;
    if (may_have_range)
	ea.cmd = skip_range(ea.cmd, TRUE, NULL);
    if (vim9script && !may_have_range)
    {
	if (ea.cmd == cmd + 1 && *cmd == '$')
	    --ea.cmd;
	p = find_ex_command(&ea, NULL, NULL, NULL);
	if (ea.cmdidx == CMD_SIZE)
	{
	    char_u *ar = skip_range(ea.cmd, TRUE, NULL);
	    if (ar > ea.cmd && !ea.skip)
	    {
	    }
	}
    }
    else
	p = find_ex_command(&ea, NULL, NULL, NULL);
    ea.cmd = cmd;
    if (!IS_USER_CMDIDX(ea.cmdidx))
    {
	if (ea.cmdidx != CMD_SIZE)
	    ea.addr_type = cmdnames[(int)ea.cmdidx].cmd_addr_type;
	else
	    ea.addr_type = ADDR_LINES;
	if (ea.cmdidx == CMD_wincmd && p != NULL)
	    get_wincmd_addr_type(skipwhite(p), &ea);
    }
    if (!may_have_range)
	ea.line1 = ea.line2 = default_address(&ea);
    else if (parse_cmd_address(&ea, &errormsg, FALSE) == FAIL)
	goto doend;
    ea.cmd = skipwhite(ea.cmd);
    while (*ea.cmd == ':')
	ea.cmd = skipwhite(ea.cmd + 1);
    if (*ea.cmd == NUL || comment_start(ea.cmd, starts_with_colon)
			       || (ea.nextcmd = check_nextcmd(ea.cmd)) != NULL)
    {
	if (ea.skip)	    // skip this if inside :if
	    goto doend;
	errormsg = ex_range_without_command(&ea);
