    char_u *
ga_concat_strings(garray_T *gap, char *sep)
{
    int		sep_len = (int)STRLEN(sep);
    for (i = 0; i < gap->ga_len; ++i)
	len += (int)STRLEN(((char_u **)(gap->ga_data))[i]) + sep_len;
    s = alloc(len + 1);
    if (s == NULL)
	return NULL;
    *s = NUL;
    p = s;
    for (i = 0; i < gap->ga_len; ++i)
    {
	if (p != s)
	{
	    STRCPY(p, sep);
	    p += sep_len;
	}
	STRCPY(p, ((char_u **)(gap->ga_data))[i]);  // The line where the warning is located
	p += STRLEN(p);
    }
    return s;

