    if (IS_USER_CMDIDX(ea.cmdidx))
    {
    }
    else
	if (ea.errmsg != NULL)
	    errormsg = ea.errmsg;
    }
    if (errormsg != NULL && *errormsg != NUL && !did_emsg)
    {
	if ((sourcing || !KeyTyped) && !did_append_cmd)
	{
	    if (errormsg != (char *)IObuff)
