    char_u	*newval,
    set_op_T	op)
{
    char_u *s = option_expand(opt_idx, newval);
    if (s == NULL)
	return newval;
    unsigned newlen = (unsigned)STRLEN(s) + 1;
    if (op != OP_NONE)
