		    var = p;
	    if (var != NULL && *var != NUL
		    && (STRLEN(var) + STRLEN(tail) + 1 < (unsigned)dstlen))
		STRCPY(dst, var);  // The line where the warning is located
		dstlen -= (int)STRLEN(var);
		c = (int)STRLEN(var);
