	if (copy_char)	    // copy at least one char
	    at_start = FALSE;
	    if (src[0] == '\\' && src[1] != NUL)
		*dst++ = *src++;
		--dstlen;
	    else if ((src[0] == ' ' || src[0] == ',') && !one)
		at_start = TRUE;
	    if (dstlen > 0)
		*dst++ = *src++;
		--dstlen;
		if (startstr != NULL && src - startstr_len >= srcp
			&& STRNCMP(src - startstr_len, startstr,
		    at_start = TRUE;
    *dst = NUL;

