    int
op_change(oparg_T *oap)
{
    long		pre_indent = 0;
    l = oap->start.col;
    if (oap->motion_type == MLINE)
    {
	l = 0;
    }
    if (curbuf->b_ml.ml_flags & ML_EMPTY)
    {
	if (u_save_cursor() == FAIL)
	    return FALSE;
    }
    else if (op_delete(oap) == FAIL)
	return FALSE;
    if ((l > curwin->w_cursor.col) && !LINEEMPTY(curwin->w_cursor.lnum)
							 && !virtual_op)
	inc_cursor();
    if (oap->block_mode)
    {
	if (virtual_op && (curwin->w_cursor.coladd > 0
						    || gchar_cursor() == NUL))
	    coladvance_force(getviscol());
	firstline = ml_get(oap->start.lnum);
	pre_indent = (long)getwhitecols(firstline);
	bd.textcol = curwin->w_cursor.col;
    }
    if (oap->motion_type == MLINE)
	fix_indent();
    if (oap->block_mode && oap->start.lnum != oap->end.lnum && !got_int)
    {
	firstline = ml_get(oap->start.lnum);
	if (bd.textcol > (colnr_T)pre_indent)
	{
	    long new_indent = (long)getwhitecols(firstline);
	    pre_textlen += new_indent - pre_indent;
	    bd.textcol += new_indent - pre_indent;
	}
	ins_len = (int)ml_get_len(oap->start.lnum) - pre_textlen;
	if (ins_len > 0)
	{
	    if ((ins_text = alloc(ins_len + 1)) != NULL)
	    {
		vim_strncpy(ins_text, firstline + bd.textcol, ins_len);
		for (linenr = oap->start.lnum + 1; linenr <= oap->end.lnum;
								     linenr++)
		{
		    block_prep(oap, &bd, linenr, TRUE);
		    if (!bd.is_short || virtual_op)
		    {
			if (bd.is_short)
			{
			    vpos.lnum = linenr;
			    (void)getvpos(&vpos, oap->start_vcol);
			}
			else
			    vpos.coladd = 0;
			oldp = ml_get(linenr);
			newp = alloc(ml_get_len(linenr) + vpos.coladd + ins_len + 1);
			if (newp == NULL)
			    continue;
			mch_memmove(newp, oldp, (size_t)bd.textcol);
			newlen = bd.textcol;
			newlen += vpos.coladd;
			mch_memmove(newp + newlen, ins_text, ins_len);
			STRCPY(newp + newlen + ins_len, oldp + bd.textcol);  // The line where the warning is located
		    }
		}
	    }
	}
    }

    int
op_replace(oparg_T *oap, int c)
{
    char_u		*after_p = NULL;
    int			had_ctrl_v_cr = FALSE;
    if ((curbuf->b_ml.ml_flags & ML_EMPTY ) || oap->empty)
	return OK;	    // nothing to do
    if (c == REPLACE_CR_NCHAR)
    {
	had_ctrl_v_cr = TRUE;
    }
    else if (c == REPLACE_NL_NCHAR)
	had_ctrl_v_cr = TRUE;
    }
    if (has_mbyte)
	mb_adjust_opend(oap);
    if (u_save((linenr_T)(oap->start.lnum - 1),
				       (linenr_T)(oap->end.lnum + 1)) == FAIL)
	return FAIL;
    if (oap->block_mode)
    {
	bd.is_MAX = (curwin->w_curswant == MAXCOL);
	for ( ; curwin->w_cursor.lnum <= oap->end.lnum; ++curwin->w_cursor.lnum)
	{
	    block_prep(oap, &bd, curwin->w_cursor.lnum, TRUE);
	    if (bd.textlen == 0 && (!virtual_op || bd.is_MAX))
		continue;	    // nothing to replace
	    if (virtual_op && bd.is_short && *bd.textstart == NUL)
	    {
		vpos.lnum = curwin->w_cursor.lnum;
		getvpos(&vpos, oap->start_vcol);
		bd.startspaces += vpos.coladd;
	    }
	    else
		n = (bd.startspaces ? bd.start_char_vcols - 1 : 0);
	    n += (bd.endspaces
		    && !bd.is_oneChar
		    && bd.end_char_vcols > 0) ? bd.end_char_vcols - 1 : 0;
	    numc = oap->end_vcol - oap->start_vcol + 1;
	    if (bd.is_short && (!virtual_op || bd.is_MAX))
		numc -= (oap->end_vcol - bd.end_vcol) + 1;
	    if ((*mb_char2cells)(c) > 1)
	    {
		if ((numc & 1) && !bd.is_short)
		{
		    ++bd.endspaces;
		}
		numc = numc / 2;
	    }
	    num_chars = numc;
	    numc *= (*mb_char2len)(c);
	    n += numc - bd.textlen;
	    oldp = ml_get_curline();
	    oldlen = ml_get_curline_len();
	    newp = alloc(oldlen + 1 + n);
	    if (newp == NULL)
		continue;
	    vim_memset(newp, NUL, (size_t)(oldlen + 1 + n));
	    mch_memmove(newp, oldp, (size_t)bd.textcol);
	    newlen = bd.textcol;
	    newlen += bd.startspaces;
	    if (had_ctrl_v_cr || (c != '\r' && c != '\n'))
	    {
		if (has_mbyte)
		{
		    while (--num_chars >= 0)
			newlen += (*mb_char2bytes)(c, newp + newlen);
		}
		else
		    newlen += numc;
		}
		if (!bd.is_short)
		{
		    STRCPY(newp + newlen + bd.endspaces,  // The line where the warning is located
		}
	    }
	    else
		if (after_p != NULL)
		    STRCPY(after_p, oldp + bd.textcol + bd.textlen);
	    }
	    if (after_p != NULL)
	    {
		oap->end.lnum++;
		vim_free(after_p);
	    }
	}
    }
    else
    }

