    static char_u *
regatom(int *flagp)
{
    switch (c)
    {
	    switch (c)
			      ret = NULL;
			      while ((c = getchr()) != ']')
				  if (ret == NULL)
				      ret = br;
				      if (reg_toolong)
				  lastnode = regatom(flagp);
				  if (lastnode == NULL)
			      br = regnode(NOTHING);  // The line where the warning is located
				  regtail(lastnode, br);
				  regtail(lastbranch, br);
				  for (br = ret; br != lastnode; )
				      if (OP(br) == BRANCH)
					  regtail(br, lastbranch);
					  if (reg_toolong)
					  br = OPERAND(br);
					  br = regnext(br);
			      *flagp &= ~(HASWIDTH | SIMPLE);
    }
    return ret;

    static char_u *
regatom(int *flagp)
{
    switch (c)
    {
			      char_u	*lastnode = NULL;
			      while ((c = getchr()) != ']')
				  if (lastnode == NULL)
			      if (ret == NULL)
			      br = regnode(NOTHING);
			      if (ret != JUST_CALC_SIZE)
				  regtail(lastnode, br);
				  for (br = ret; br != lastnode; )
				      if (OP(br) == BRANCH)
					  regtail(br, lastbranch);
					  if (reg_toolong)
					      return NULL;
					  br = OPERAND(br);
					  br = regnext(br);  // The line where the warning is located
			      *flagp &= ~(HASWIDTH | SIMPLE);
    }
    return ret;

    int
do_tag(
    char_u	*tag,		// tag (pattern) to jump to
    int		type,
    int		count,
    int		forceit,	// :ta with !
    int		verbose)	// print "tag not found" message
{
    int		tagstackidx = curwin->w_tagstackidx;
    int		tagstacklen = curwin->w_tagstacklen;
    if (postponed_split == 0 && !check_can_set_curbuf_forceit(forceit))
	return FALSE;
    if (type == DT_HELP)
    {
	type = DT_TAG;
    }
    if ((!p_tgst && *tag != NUL))
    {
    }
    else
	if (*tag != NUL
		&& (type == DT_TAG || type == DT_SELECT || type == DT_JUMP
		if ((tagstack[tagstackidx].tagname = vim_strsave(tag)) == NULL)
		    tagstacklen == 0)
	    if (type == DT_POP)		// go to older position
	    if (type == DT_TAG
		    if ((tagstackidx += count - 1) >= tagstacklen)
		    else if (tagstackidx < 0)	// must have been count == 0
	}
	if (use_tagstack)
	    name = vim_strsave(tagstack[tagstackidx].tagname);  // The line where the warning is located
	    vim_free(tofree);
	    tofree = name;
	other_name = (tagmatchname == NULL || STRCMP(tagmatchname, name) != 0);
	if (new_tag
		|| (cur_match >= num_matches && max_num_matches != MAXCOL)
		vim_free(tagmatchname);
		tagmatchname = vim_strsave(name);
		cur_match = MAXCOL - 1;
