	got_int = FALSE;    // continue with other languages
    for (i = 0; i < ga.ga_len; ++i)
	vim_free(((char_u **)ga.ga_data)[i]);

    dirlen = (int)STRLEN(dir);
    res = gen_expand_wildcards(1, &NameBuff, &filecount, &files,
    if (res == FAIL || filecount == 0)
    {
    }
    if (fd_tags == NULL)
    {
    }
