static void id3v2_parse(AVIOContext *pb, AVDictionary **metadata,
                        AVFormatContext *s, int len, uint8_t version,
                        uint8_t flags, ExtraMetaList *extra_meta)
{
    char tag[5];
    int64_t next, end = avio_tell(pb);
    unsigned char *buffer = NULL;
    int buffer_size       = 0;
    if (end > INT64_MAX - len - 10)
        return;
    av_log(s, AV_LOG_DEBUG, "id3v2 ver:%d flags:%02X len:%d\n", version, flags, len);
    switch (version) {
        if (flags & 0x40) {
        isv34     = 0;
        comm_frame = "COM";
        isv34     = 1;
        comm_frame = "COMM";
    }
    unsync = flags & 0x80;
    if (isv34 && flags & 0x40) { /* Extended header present, just skip over it */
        int extlen = get_size(pb, 4);
        if (version == 4)
            extlen -= 4;
        if (extlen < 0) {
        }
        avio_skip(pb, extlen);
    }
    while (len >= taghdrlen) {
        unsigned int tflags = 0;
        int tunsync         = 0;
        int tcomp           = 0;
        int tencr           = 0;
        if (isv34) {
            if (avio_read(pb, tag, 4) < 4)
                break;
            tag[4] = 0;
            if (version == 3) {
                tlen = avio_rb32(pb);
            } else {
                tlen = avio_rb32(pb);
                if (tlen > 0x7f) {
                    if (tlen < len) {
                        int64_t cur = avio_tell(pb);
                        if (ffio_ensure_seekback(pb, 2 /* tflags */ + tlen + 4 /* next tag */))
                        if (check_tag(pb, cur + 2 + size_to_syncsafe(tlen), 4) == 1)
                            tlen = size_to_syncsafe(tlen);
                        else if (check_tag(pb, cur + 2 + tlen, 4) != 1)
                        avio_seek(pb, cur, SEEK_SET);
                        tlen = size_to_syncsafe(tlen);
            }
            tflags  = avio_rb16(pb);
            tunsync = tflags & ID3v2_FLAG_UNSYNCH;
        } else {
            if (avio_read(pb, tag, 3) < 3)
            tag[3] = 0;
            tlen   = avio_rb24(pb);
        }
        if (tlen > (1<<28))
            break;
        len -= taghdrlen + tlen;
        if (len < 0)
            break;
        next = avio_tell(pb) + tlen;
        if (!tlen) {
            if (tag[0])
                av_log(s, AV_LOG_DEBUG, "Invalid empty frame %s, skipping.\n",
                       tag);
        }
        if (tflags & ID3v2_FLAG_DATALEN) {
            if (tlen < 4)
                break;
            dlen = avio_rb32(pb);
            tlen -= 4;
        } else
            dlen = tlen;
        tcomp = tflags & ID3v2_FLAG_COMPRESSION;
        tencr = tflags & ID3v2_FLAG_ENCRYPTION;
        if (tencr || (!CONFIG_ZLIB && tcomp)) {
            if (!tcomp)
                type = "encrypted";
            else if (!tencr)
                type = "compressed";
                type = "encrypted and compressed";
            av_log(s, AV_LOG_WARNING, "Skipping %s ID3v2 frame %s.\n", type, tag);
            avio_skip(pb, tlen);
        } else if (tag[0] == 'T' ||
                   !memcmp(tag, "USLT", 4) ||
                   !strcmp(tag, comm_frame) ||
                   (extra_meta &&
                    (extra_func = get_extra_meta_func(tag, isv34)))) {
            pbx = pb;
            if (unsync || tunsync || tcomp) {
                av_fast_malloc(&buffer, &buffer_size, tlen);
                if (!buffer) {
                    av_log(s, AV_LOG_ERROR, "Failed to alloc %d bytes\n", tlen);
            if (unsync || tunsync) {
                uint8_t *b = buffer;
                if (avio_read(pb, buffer, tlen) != tlen) {
                    av_log(s, AV_LOG_ERROR, "Failed to read tag data\n");
                    *b++ = *t++;
                ffio_init_read_context(&pb_local, buffer, b - buffer);
                tlen = b - buffer;
                pbx  = &pb_local.pub; // read from sync buffer
            if (tag[0] == 'T')
                read_ttag(s, pbx, tlen, metadata, tag);
            else if (!memcmp(tag, "USLT", 4))
                read_uslt(s, pbx, tlen, metadata);
            else if (!strcmp(tag, comm_frame))
                read_comment(s, pbx, tlen, metadata);
                extra_func->read(s, pbx, tlen, tag, extra_meta, isv34);  // The line where the warning is located
        } else if (!tag[0]) {
            if (tag[1])
                av_log(s, AV_LOG_WARNING, "invalid frame id, assuming padding\n");
            avio_skip(pb, tlen);
        }
        avio_seek(pb, next, SEEK_SET);
    }
    if (version == 4 && flags & 0x10)
        end += 10;
        av_log(s, AV_LOG_INFO, "ID3v2.%d tag skipped, cannot handle %s\n",
    avio_seek(pb, end, SEEK_SET);

int split_commandline(OptionParseContext *octx, int argc, char *argv[],
                      const OptionDef *options,
                      const OptionGroupDef *groups, int nb_groups)
{
    int optindex = 1;
    int dashdash = -2;
    prepare_app_arguments(&argc, &argv);
    ret = init_parse_context(octx, groups, nb_groups);
    if (ret < 0)
        return ret;
    av_log(NULL, AV_LOG_DEBUG, "Splitting the commandline.\n");
    while (optindex < argc) {
        const char *opt = argv[optindex++], *arg;
        av_log(NULL, AV_LOG_DEBUG, "Reading option '%s' ...", opt);
        if (opt[0] == '-' && opt[1] == '-' && !opt[2]) {  // The line where the warning is located
            dashdash = optindex;
        }
        if (opt[0] != '-' || !opt[1] || dashdash+1 == optindex) {
            ret = finish_group(octx, 0, opt);
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as %s.\n", groups[0].name);
        }
        opt++;
        group_idx = match_group_separator(groups, nb_groups, opt);
        if (group_idx >= 0) {
            GET_ARG(arg);
            ret = finish_group(octx, group_idx, arg);
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as %s with argument '%s'.\n",
        }
        po = find_option(options, opt);
        if (po->name) {
            if (po->flags & OPT_EXIT) {
                arg = argv[optindex++];
            } else if (opt_has_arg(po)) {
                GET_ARG(arg);
                arg = "1";
            }
            ret = add_opt(octx, po, opt, arg);
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "
                   "argument '%s'.\n", po->name, po->help, arg);
        }
        if (argv[optindex]) {
            ret = opt_default(NULL, opt, argv[optindex]);
            if (ret >= 0) {
                av_log(NULL, AV_LOG_DEBUG, " matched as AVOption '%s' with "
                       "argument '%s'.\n", opt, argv[optindex]);
                optindex++;
            } else if (ret != AVERROR_OPTION_NOT_FOUND) {
                av_log(NULL, AV_LOG_ERROR, "Error parsing option '%s' "
            }
        }
        if (opt[0] == 'n' && opt[1] == 'o' &&
            (po = find_option(options, opt + 2)) &&
            po->name && po->type == OPT_TYPE_BOOL) {
            ret = add_opt(octx, po, opt, "0");
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "
                   "argument 0.\n", po->name, po->help);
        }
        av_log(NULL, AV_LOG_ERROR, "Unrecognized option '%s'.\n", opt);
    }
    if (octx->cur_group.nb_opts || codec_opts || format_opts)
        av_log(NULL, AV_LOG_WARNING, "Trailing option(s) found in the "
               "command: may be ignored.\n");
    av_log(NULL, AV_LOG_DEBUG, "Finished splitting the commandline.\n");
    return 0;

