                      const OptionGroupDef *groups, int nb_groups)
{
    int optindex = 1;
    int dashdash = -2;
    prepare_app_arguments(&argc, &argv);
    ret = init_parse_context(octx, groups, nb_groups);
    if (ret < 0)
        return ret;
    av_log(NULL, AV_LOG_DEBUG, "Splitting the commandline.\n");
    while (optindex < argc) {
        const char *opt = argv[optindex++], *arg;
        av_log(NULL, AV_LOG_DEBUG, "Reading option '%s' ...", opt);
        if (opt[0] == '-' && opt[1] == '-' && !opt[2]) {  // The line where the warning is located
            dashdash = optindex;
        }
        if (opt[0] != '-' || !opt[1] || dashdash+1 == optindex) {
            ret = finish_group(octx, 0, opt);
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as %s.\n", groups[0].name);
        }
        opt++;
        group_idx = match_group_separator(groups, nb_groups, opt);
        if (group_idx >= 0) {
            GET_ARG(arg);
            ret = finish_group(octx, group_idx, arg);
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as %s with argument '%s'.\n",
        }
        po = find_option(options, opt);
        if (po->name) {
            if (po->flags & OPT_EXIT) {
                arg = argv[optindex++];
            } else if (opt_has_arg(po)) {
                GET_ARG(arg);
                arg = "1";
            }
            ret = add_opt(octx, po, opt, arg);
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "
                   "argument '%s'.\n", po->name, po->help, arg);
        }
        if (argv[optindex]) {
            ret = opt_default(NULL, opt, argv[optindex]);
            if (ret >= 0) {
                av_log(NULL, AV_LOG_DEBUG, " matched as AVOption '%s' with "
                       "argument '%s'.\n", opt, argv[optindex]);
                optindex++;
            } else if (ret != AVERROR_OPTION_NOT_FOUND) {
                av_log(NULL, AV_LOG_ERROR, "Error parsing option '%s' "
            }
        }
        if (opt[0] == 'n' && opt[1] == 'o' &&
            (po = find_option(options, opt + 2)) &&
            po->name && po->type == OPT_TYPE_BOOL) {
            ret = add_opt(octx, po, opt, "0");
            if (ret < 0)
                return ret;
            av_log(NULL, AV_LOG_DEBUG, " matched as option '%s' (%s) with "
                   "argument 0.\n", po->name, po->help);
        }
        av_log(NULL, AV_LOG_ERROR, "Unrecognized option '%s'.\n", opt);
    }
    if (octx->cur_group.nb_opts || codec_opts || format_opts)
        av_log(NULL, AV_LOG_WARNING, "Trailing option(s) found in the "
               "command: may be ignored.\n");
    av_log(NULL, AV_LOG_DEBUG, "Finished splitting the commandline.\n");
    return 0;

static int output_packet(AVFormatContext *ctx, int flush)
{
    int best_i = -1;
    int best_score = INT_MIN;
    const int64_t max_delay = av_rescale(ctx->max_delay, 90000, AV_TIME_BASE);
    for (i = 0; i < ctx->nb_streams; i++) {
        AVStream *st = ctx->streams[i];
        StreamInfo *stream = st->priv_data;
        int rel_space = 1024LL * space / stream->max_buffer_size;
        if (s->packet_size > avail_data && !flush
            && st->codecpar->codec_type != AVMEDIA_TYPE_SUBTITLE)
        if (next_pkt && next_pkt->dts - scr > max_delay && !ignore_delay)
            rel_space += 1<<28;
        if (rel_space > best_score) {
            best_score  = rel_space;
            best_i      = i;
    if (best_i < 0) {
        int has_premux = 0;
        for (i = 0; i < ctx->nb_streams; i++) {
            AVStream *st = ctx->streams[i];
            StreamInfo *stream = st->priv_data;
            has_premux |= !!stream->premux_packet;
        }
        if (best_dts < INT64_MAX) {
            av_log(ctx, AV_LOG_TRACE, "bumping scr, scr:%f, dts:%f\n",
            if (scr >= best_dts + 1 && !ignore_constraints) {
                av_log(ctx, AV_LOG_ERROR,
            }
            scr = FFMAX(best_dts + 1, scr);
            if (remove_decoded_packets(ctx, scr) < 0)
                return -1;
        } else if (has_premux && flush) {
            av_log(ctx, AV_LOG_ERROR,
            return 0;
    }
    st     = ctx->streams[best_i];
    stream = st->priv_data;
    timestamp_packet = stream->premux_packet;
    if (timestamp_packet->unwritten_size == timestamp_packet->size) {  // The line where the warning is located
        trailer_size = 0;
    } else {
        trailer_size     = timestamp_packet->unwritten_size;
        timestamp_packet = timestamp_packet->next;
    }
    if (timestamp_packet) {
        av_log(ctx, AV_LOG_TRACE, "dts:%f pts:%f scr:%f stream:%d\n",
                timestamp_packet->dts / 90000.0,
                timestamp_packet->pts / 90000.0,
        es_size = flush_packet(ctx, best_i, timestamp_packet->pts,
    } else {
        av_assert0(av_fifo_can_read(stream->fifo) == trailer_size);
        es_size = flush_packet(ctx, best_i, AV_NOPTS_VALUE, AV_NOPTS_VALUE, scr,
    }
    if (s->is_vcd) {
        while ((vcd_pad_bytes = get_vcd_padding_size(ctx, stream->premux_packet->pts)) >= s->packet_size) {
            put_vcd_padding_sector(ctx);
        }
    }
    stream->buffer_index += es_size;
    while (stream->premux_packet &&
           stream->premux_packet->unwritten_size <= es_size) {
        es_size              -= stream->premux_packet->unwritten_size;
    }
    if (es_size) {
        av_assert0(stream->premux_packet);
        stream->premux_packet->unwritten_size -= es_size;
    }
    if (remove_decoded_packets(ctx, s->last_scr) < 0)
        return -1;

