                    FAIL(AVERROR_INVALIDDATA);
                FAIL(AVERROR_BUG);
            }
        }
        switch ((ParseDirective)(dir - syntax)) {
            if (strcmp(arg_kw[0], "version") || strcmp(arg_kw[1], "1.0")) {
