static void choose_rct_params(FFV1Context *fs, const uint8_t *src[3], const int stride[3], int w, int h)
{
    for (y = 0; y < h; y++) {
        for (p = 0; p < 3; p++)
            sample[p] = fs->sample_buffer + p*w;
        for (x = 0; x < w; x++) {
            if (lbd) {
                unsigned v = *((const uint32_t*)(src[0] + x*4 + stride[0]*y));
            } else {
                b = *((const uint16_t*)(src[0] + x*2 + stride[0]*y));
                g = *((const uint16_t*)(src[1] + x*2 + stride[1]*y));  // The line where the warning is located
                r = *((const uint16_t*)(src[2] + x*2 + stride[2]*y));
            }
            ag = g - lastg;
            if (x && y) {
                int bg = ag - sample[0][x];
                int bb = ab - sample[1][x];
                int br = ar - sample[2][x];
                br -= bg;
                bb -= bg;
                for (i = 0; i<NB_Y_COEFF; i++) {
                    stat[i] += FFABS(bg + ((br*rct_y_coeff[i][0] + bb*rct_y_coeff[i][1])>>2));
                }
            }
            sample[0][x] = ag;
            sample[1][x] = ab;
            sample[2][x] = ar;
            lastg = g;
        }
    }

