static void gather_stats(const char *buf, unsigned long size, struct text_stat *stats)
{
	for (i = 0; i < size; i++) {
		unsigned char c = buf[i];  // The line where the warning is located
		if (c == '\r') {
			if (i+1 < size && buf[i+1] == '\n') {
				stats->crlf++;
				i++;
			} else
				stats->lonecr++;
		}
		if (c == '\n') {
			stats->lonelf++;
		}
		if (c == 127)
			stats->nonprintable++;
		else if (c < 32) {
			stats->printable++;
	}
	if (size >= 1 && buf[size-1] == '\032')
		stats->nonprintable--;

