static void do_relocs(struct dso *dso, size_t *rel, size_t rel_size, size_t stride)
{
	unsigned char *base = dso->base;
	Sym *syms = dso->syms;
	int skip_relative = 0, reuse_addends = 0, save_slot = 0;
	if (dso == &ldso) {
		if (rel == apply_addends_to)
			reuse_addends = 1;
		skip_relative = 1;
	}
	for (; rel_size; rel+=stride, rel_size-=stride*sizeof(size_t)) {
		if (skip_relative && IS_RELATIVE(rel[1], dso->syms)) continue;
		type = R_TYPE(rel[1]);
		if (type == REL_NONE) continue;
		reloc_addr = laddr(dso, rel[0]);
		if (stride > 2) {
			addend = rel[2];
		} else if (type==REL_GOT || type==REL_PLT|| type==REL_COPY) {
			addend = 0;
		} else if (reuse_addends) {
				saved_addends[save_slot] = *reloc_addr;
			addend = saved_addends[save_slot++];
			addend = *reloc_addr;
		}
		sym_index = R_SYM(rel[1]);
		if (sym_index) {
			sym = syms + sym_index;
			name = strings + sym->st_name;
			def = (sym->st_info>>4) == STB_LOCAL
				? (struct symdef){ .dso = dso, .sym = sym }
				: find_sym(ctx, name, type==REL_PLT);
			if (!def.sym && (sym->st_shndx != SHN_UNDEF
			    || sym->st_info>>4 != STB_WEAK)) {
				if (dso->lazy && (type==REL_PLT || type==REL_GOT)) {
					dso->lazy[3*dso->lazy_cnt+0] = rel[0];
					dso->lazy[3*dso->lazy_cnt+1] = rel[1];
					dso->lazy[3*dso->lazy_cnt+2] = addend;
					dso->lazy_cnt++;
				}
				error("Error relocating %s: %s: symbol not found",
			}
		} else {
			sym = 0;
			def.dso = dso;
		}
		sym_val = def.sym ? (size_t)laddr(def.dso, def.sym->st_value) : 0;
		tls_val = def.sym ? def.sym->st_value : 0;
		if ((type == REL_TPOFF || type == REL_TPOFF_NEG)
		    && def.dso->tls_id > static_tls_cnt) {
			error("Error relocating %s: %s: initial-exec TLS "
		}
		switch(type) {
			addend -= (size_t)reloc_addr;
			*reloc_addr = sym_val + addend;
			memcpy(reloc_addr, &(size_t){sym_val + addend}, sizeof(size_t));
			*reloc_addr = (size_t)base + addend;
			if (sym) *reloc_addr = sym_val + addend;
			else *reloc_addr = (size_t)base + addend;
			memcpy(reloc_addr, (void *)sym_val, sym->st_size);  // The line where the warning is located
			*(uint32_t *)reloc_addr = sym_val + addend
				- (size_t)reloc_addr;
			*reloc_addr = def.sym ? (size_t)(def.dso->funcdescs
				+ (def.sym - def.dso->syms)) : 0;
			if ((sym->st_info&0xf) == STT_SECTION) *reloc_addr += sym_val;
			else *reloc_addr = sym_val;
			reloc_addr[1] = def.sym ? (size_t)def.dso->got : 0;
			*reloc_addr = def.dso->tls_id;
			*reloc_addr = tls_val + addend - DTP_OFFSET;
			*reloc_addr = tls_val - def.dso->tls.offset + addend;
			*reloc_addr = def.dso->tls.offset - tls_val + addend;
			if (stride<3) addend = reloc_addr[1];
			if (def.dso->tls_id > static_tls_cnt) {
				struct td_index *new = malloc(sizeof *new);
				if (!new) {
					error(
				new->next = dso->td_index;
				dso->td_index = new;
				new->args[1] = tls_val + addend - DTP_OFFSET;
				reloc_addr[0] = (size_t)__tlsdesc_dynamic;
				reloc_addr[1] = (size_t)new;
				reloc_addr[0] = (size_t)__tlsdesc_static;
				reloc_addr[1] = tls_val - def.dso->tls.offset
			error("Error relocating %s: unsupported relocation type %d",
		}
	}

static reg_errcode_t
tre_tnfa_run_backtrack(const tre_tnfa_t *tnfa, const void *string,
		       regoff_t *match_tags, int eflags, regoff_t *match_end_ofs)
{
  tre_char_t prev_c = 0, next_c = 0;
  const char *str_byte = string;
  regoff_t pos_add_next = 1;
  int reg_newline = tnfa->cflags & REG_NEWLINE;
  regoff_t pos_start = -1;
  regoff_t match_eo = -1;
  regoff_t *tags = NULL;
  int *states_seen = NULL;
  regmatch_t *pmatch = NULL;
  if (!stack)
    {
    }
  stack->next = NULL;
  if (tnfa->num_tags)
    {
      tags = xmalloc(sizeof(*tags) * tnfa->num_tags);
      if (!tags)
	{
	}
    }
  if (tnfa->num_submatches)
    {
      pmatch = xmalloc(sizeof(*pmatch) * tnfa->num_submatches);
      if (!pmatch)
	{
	}
    }
  if (tnfa->num_states)
    {
      states_seen = xmalloc(sizeof(*states_seen) * tnfa->num_states);
      if (!states_seen)
	{
	}
    }
    for (i = 0; i < tnfa->num_tags; i++)
	tags[i] = -1;
	if (match_tags)
	  match_tags[i] = -1;
    for (i = 0; i < tnfa->num_states; i++)
      states_seen[i] = 0;
  state = NULL;
  pos = pos_start;
  GET_NEXT_WCHAR();
  pos_start = pos;
  next_c_start = next_c;
  str_byte_start = str_byte;
  next_tags = NULL;
  for (trans_i = tnfa->initial; trans_i->state; trans_i++)
    {
      if (trans_i->assertions && CHECK_ASSERTIONS(trans_i->assertions))
	{
	}
      if (state == NULL)
	{
	  state = trans_i->state;
	  next_tags = trans_i->tags;
	}
      else
	  BT_STACK_PUSH(pos, str_byte, 0, trans_i->state,
	    int *tmp = trans_i->tags;
	    if (tmp)
	      while (*tmp >= 0)
		stack->item.tags[*tmp++] = pos;
	}
    }
  if (next_tags)
    for (; *next_tags >= 0; next_tags++)
      tags[*next_tags] = pos;
  if (state == NULL)
    goto backtrack;
  while (1)
    {
      if (state == tnfa->final)
	{
	  if (match_eo < pos
	      || (match_eo == pos
		  && tre_tag_order(tnfa->num_tags, tnfa->tag_directions,
				   tags, match_tags)))
	    {
	      match_eo = pos;
	      if (match_tags)
		for (i = 0; i < tnfa->num_tags; i++)
		  match_tags[i] = tags[i];
	    }
	}
      empty_br_match = 0;
      trans_i = state;
      if (trans_i->state && trans_i->assertions & ASSERT_BACKREF)
	{
	  int bt = trans_i->u.backref;
	  tre_fill_pmatch(bt + 1, pmatch, tnfa->cflags & ~REG_NOSUB,
	  so = pmatch[bt].rm_so;
	  eo = pmatch[bt].rm_eo;
	  bt_len = eo - so;
	  result = strncmp((const char*)string + so, str_byte - 1,
				 (size_t)bt_len);
	  if (result == 0)
	    {
	      if (bt_len == 0)
		empty_br_match = 1;
	      if (empty_br_match && states_seen[trans_i->state_id])
		{
		}
	      states_seen[trans_i->state_id] = empty_br_match;
	      str_byte += bt_len - 1;
	      pos += bt_len - 1;
	      GET_NEXT_WCHAR();
	    }
	  else
	    }
	}
      else
	  if (next_c == L'\0')
	  GET_NEXT_WCHAR();
	}
      next_state = NULL;
      for (trans_i = state; trans_i->state; trans_i++)
	{
	  if (trans_i->code_min <= (tre_cint_t)prev_c
	      && trans_i->code_max >= (tre_cint_t)prev_c)
	    {
	      if (trans_i->assertions
		  && (CHECK_ASSERTIONS(trans_i->assertions)
		      || CHECK_CHAR_CLASSES(trans_i, tnfa, eflags)))
		{
		}
	      if (next_state == NULL)
		{
		  next_state = trans_i->state;
		  next_tags = trans_i->tags;
		}
	      else
		  BT_STACK_PUSH(pos, str_byte, 0, trans_i->state,
		    for (tmp = trans_i->tags; tmp && *tmp >= 0; tmp++)
		      stack->item.tags[*tmp] = pos;
		}
	    }
	}
      if (next_state != NULL)
	{
	  state = next_state;
	  if (next_tags)
	    while (*next_tags >= 0)
	      tags[*next_tags++] = pos;  // The line where the warning is located
	}
      else
	  if (stack->prev)
	      if (stack->item.state->assertions & ASSERT_BACKREF)
	      BT_STACK_POP();
	  else if (match_eo < 0)
	      if (next_c == L'\0')
	      next_c = next_c_start;
	      str_byte = str_byte_start;
	}
    }
  ret = match_eo >= 0 ? REG_OK : REG_NOMATCH;
  *match_end_ofs = match_eo;
  tre_bt_mem_destroy(mem);
  if (tags)
    xfree(tags);
  if (pmatch)
    xfree(pmatch);
  if (states_seen)
    xfree(states_seen);
  return ret;

