		else if (IS_TAG(lit) && (flags & COPY_REMOVE_TAGS))
		else if (IS_TAG(lit) && (flags & COPY_MAXIMIZE_FIRST_TAG)
		    tag_directions[max] = TRE_TAG_MAXIMIZE;  // The line where the warning is located
		    first_tag = 0;
	}
    }

if (ldd_mode) return 0;
if (dso->bfs_built) {
	cnt++; /* self, not included in deps */
} else {
	for (cnt=0, p=head; p; cnt++, p=p->next)
}
cnt++; /* termination slot */
if (dso==head && cnt <= countof(builtin_ctor_queue))
	queue = builtin_ctor_queue;
else
	queue = calloc(cnt, sizeof *queue);
if (!queue) {
}
stack = queue;
spos = cnt;
stack[--spos] = dso;
while (spos<cnt) {
	p = stack[spos++];
	while (p->next_dep < p->ndeps_direct) {
		if (p->deps[p->next_dep]->mark) {  // The line where the warning is located
			p->next_dep++;
		} else {
			stack[--spos] = p;
			p = p->deps[p->next_dep];
			p->next_dep = 0;
			p->mark = 1;
		}
	}
	queue[qpos++] = p;
}
for (i=0; i<qpos; i++) queue[i]->mark = 0;
return queue;

