			if (!scd->state) {
				if (*inb < 2) goto starved;
				c = get_16((void *)*in, 0);
				scd->state = type==UCS2
					? c==0xfffe ? UCS2LE : UCS2BE
					: c==0xfffe ? UTF_16LE : UTF_16BE;
				if (c == 0xfffe || c == 0xfeff)
					l = 2;
			type = scd->state;
		case UTF_32:
			l = 0;
			if (!scd->state) {
				if (*inb < 4) goto starved;
				c = get_32((void *)*in, 0);
				scd->state = c==0xfffe0000 ? UTF_32LE : UTF_32BE;
				if (c == 0xfffe0000 || c == 0xfeff)
					l = 4;
			type = scd->state;
		case SHIFT_JIS:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (c-129 <= 159-129) c -= 129;
		case EUC_JP:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (c==0x8e) {
		case ISO2022_JP:
			if (c >= 128) goto ilseq;
			if (c == '\033') {
				if (*inb < 3) goto starved;
				c = *((unsigned char *)*in + 1);
				d = *((unsigned char *)*in + 2);
				if (c != '(' && c != '$') goto ilseq;
				switch (128*(c=='$') + d) {
				case 'B': scd->state=0; continue;  // The line where the warning is located
				if (*inb < 2) goto starved;
				d = *((unsigned char *)*in + 1);
				c -= 0x21;
				d -= 0x21;
				if (c >= 84 || d >= 94) goto ilseq;
		case GB2312:
			if (c < 128) break;
		case GBK:
		case GB18030:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (d < 0xa1 && type == GB2312) goto ilseq;
				if (d-'0'>9 || type != GB18030)
				if (*inb < 4) goto starved;
				d = *((unsigned char *)*in + 2);
				d = *((unsigned char *)*in + 3);
		case BIG5:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (d-0x40>=0xff-0x40 || d-0x7f<0xa1-0x7f) goto ilseq;
		case EUC_KR:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			c -= 0xa1;
			d -= 0xa1;
			if (c >= 93 || d >= 94) {
			if (!c) break;
		}
	}
	*ploc = loc;
	return x;
	err = EINVAL;
	x = -1;
	errno = err;
	*ploc = loc;
	return x;

static void do_relocs(struct dso *dso, size_t *rel, size_t rel_size, size_t stride)
{
	unsigned char *base = dso->base;
	Sym *syms = dso->syms;
	int skip_relative = 0, reuse_addends = 0, save_slot = 0;
	if (dso == &ldso) {
		if (rel == apply_addends_to)
			reuse_addends = 1;
		skip_relative = 1;
	}
	for (; rel_size; rel+=stride, rel_size-=stride*sizeof(size_t)) {
		if (skip_relative && IS_RELATIVE(rel[1], dso->syms)) continue;
		type = R_TYPE(rel[1]);
		if (type == REL_NONE) continue;
		reloc_addr = laddr(dso, rel[0]);
		if (stride > 2) {
			addend = rel[2];
		} else if (type==REL_GOT || type==REL_PLT|| type==REL_COPY) {
			addend = 0;
		} else if (reuse_addends) {
				saved_addends[save_slot] = *reloc_addr;
			addend = saved_addends[save_slot++];
			addend = *reloc_addr;
		}
		sym_index = R_SYM(rel[1]);
		if (sym_index) {
			sym = syms + sym_index;
			name = strings + sym->st_name;
			def = (sym->st_info>>4) == STB_LOCAL
				? (struct symdef){ .dso = dso, .sym = sym }
				: find_sym(ctx, name, type==REL_PLT);
			if (!def.sym) def = get_lfs64(name);
			if (!def.sym && (sym->st_shndx != SHN_UNDEF
			    || sym->st_info>>4 != STB_WEAK)) {
				if (dso->lazy && (type==REL_PLT || type==REL_GOT)) {
					dso->lazy[3*dso->lazy_cnt+0] = rel[0];
					dso->lazy[3*dso->lazy_cnt+1] = rel[1];
					dso->lazy[3*dso->lazy_cnt+2] = addend;
					dso->lazy_cnt++;
				}
				error("Error relocating %s: %s: symbol not found",
			}
		} else {
			sym = 0;
			def.dso = dso;
		}
		sym_val = def.sym ? (size_t)laddr(def.dso, def.sym->st_value) : 0;
		tls_val = def.sym ? def.sym->st_value : 0;
		if ((type == REL_TPOFF || type == REL_TPOFF_NEG)
		    && def.dso->tls_id > static_tls_cnt) {
			error("Error relocating %s: %s: initial-exec TLS "
		}
		switch(type) {
			addend -= (size_t)reloc_addr;
			*reloc_addr = sym_val + addend;
			memcpy(reloc_addr, &(size_t){sym_val + addend}, sizeof(size_t));
			*reloc_addr = (size_t)base + addend;
			if (sym) *reloc_addr = sym_val + addend;
			else *reloc_addr = (size_t)base + addend;
			memcpy(reloc_addr, (void *)sym_val, sym->st_size);  // The line where the warning is located
			*(uint32_t *)reloc_addr = sym_val + addend
				- (size_t)reloc_addr;
			*reloc_addr = def.sym ? (size_t)(def.dso->funcdescs
				+ (def.sym - def.dso->syms)) : 0;
			if ((sym->st_info&0xf) == STT_SECTION) *reloc_addr += sym_val;
			else *reloc_addr = sym_val;
			reloc_addr[1] = def.sym ? (size_t)def.dso->got : 0;
			*reloc_addr = def.dso->tls_id;
			*reloc_addr = tls_val + addend - DTP_OFFSET;
			*reloc_addr = tls_val - def.dso->tls.offset + addend;
			*reloc_addr = def.dso->tls.offset - tls_val + addend;
			if (stride<3) addend = reloc_addr[1];
			if (def.dso->tls_id > static_tls_cnt) {
				struct td_index *new = malloc(sizeof *new);
				if (!new) {
					error(
				new->next = dso->td_index;
				dso->td_index = new;
				new->args[1] = tls_val + addend - DTP_OFFSET;
				reloc_addr[0] = (size_t)__tlsdesc_dynamic;
				reloc_addr[1] = (size_t)new;
				reloc_addr[0] = (size_t)__tlsdesc_static;
				reloc_addr[1] = tls_val - def.dso->tls.offset
			error("Error relocating %s: unsupported relocation type %d",
		}
	}

for (; rel_size; rel+=stride, rel_size-=stride*sizeof(size_t)) {
	if (skip_relative && IS_RELATIVE(rel[1], dso->syms)) continue;
	type = R_TYPE(rel[1]);
	if (type == REL_NONE) continue;
	reloc_addr = laddr(dso, rel[0]);
	if (stride > 2) {
