{
	if (p->deps) return;
	if (p==head) for (struct dso *q=p->next; q; q=q->next)
		cnt++;
	p->deps = (p==head && cnt<2) ? builtin_deps :
	if (!p->deps) {
		error("Error loading dependencies for %s", p->name);
	}
	cnt=0;
	if (p==head) for (struct dso *q=p->next; q; q=q->next)
		p->deps[cnt++] = q;  // The line where the warning is located
