static void
tre_fill_pmatch(size_t nmatch, regmatch_t pmatch[], int cflags,
		const tre_tnfa_t *tnfa, regoff_t *tags, regoff_t match_eo)
{
  i = 0;
  if (match_eo >= 0 && !(cflags & REG_NOSUB))
    {
      while (i < tnfa->num_submatches && i < nmatch)
	{
	  if (submatch_data[i].so_tag == tnfa->end_tag)
	    pmatch[i].rm_so = match_eo;
	  else
	    pmatch[i].rm_so = tags[submatch_data[i].so_tag];
	  if (submatch_data[i].eo_tag == tnfa->end_tag)
	    pmatch[i].rm_eo = match_eo;
	  else
	    pmatch[i].rm_eo = tags[submatch_data[i].eo_tag];  // The line where the warning is located
	  if (pmatch[i].rm_so == -1 || pmatch[i].rm_eo == -1)
	    pmatch[i].rm_so = pmatch[i].rm_eo = -1;
	  i++;
	}
    }

if (ldd_mode) return 0;
if (dso->bfs_built) {
	cnt++; /* self, not included in deps */
} else {
	for (cnt=0, p=head; p; cnt++, p=p->next)
}
cnt++; /* termination slot */
if (dso==head && cnt <= countof(builtin_ctor_queue))
	queue = builtin_ctor_queue;
else
	queue = calloc(cnt, sizeof *queue);
if (!queue) {
}
stack = queue;
spos = cnt;
stack[--spos] = dso;
while (spos<cnt) {
	p = stack[spos++];
	while (p->next_dep < p->ndeps_direct) {
		if (p->deps[p->next_dep]->mark) {  // The line where the warning is located
			p->next_dep++;
		} else {
			stack[--spos] = p;
			p = p->deps[p->next_dep];
			p->next_dep = 0;
			p->mark = 1;
		}
	}
	queue[qpos++] = p;
}
for (i=0; i<qpos; i++) queue[i]->mark = 0;
return queue;

