				if (type-UCS2BE < 2U) goto ilseq;
				if (*inb < 4) goto starved;
				d = get_16((void *)(*in + 2), type);
		case UCS2:
		case UTF_16:
			l = 0;
			if (!scd->state) {
				if (*inb < 2) goto starved;
				c = get_16((void *)*in, 0);
				scd->state = type==UCS2
					? c==0xfffe ? UCS2LE : UCS2BE
					: c==0xfffe ? UTF_16LE : UTF_16BE;
				if (c == 0xfffe || c == 0xfeff)
					l = 2;
			type = scd->state;
		case UTF_32:
			l = 0;
			if (!scd->state) {
				if (*inb < 4) goto starved;
				c = get_32((void *)*in, 0);
				scd->state = c==0xfffe0000 ? UTF_32LE : UTF_32BE;
				if (c == 0xfffe0000 || c == 0xfeff)
					l = 4;
			type = scd->state;
		case SHIFT_JIS:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (c-129 <= 159-129) c -= 129;
		case EUC_JP:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (c==0x8e) {
		case ISO2022_JP:
			if (c >= 128) goto ilseq;
			if (c == '\033') {
				if (*inb < 3) goto starved;
				c = *((unsigned char *)*in + 1);
				d = *((unsigned char *)*in + 2);
				if (c != '(' && c != '$') goto ilseq;
				switch (128*(c=='$') + d) {
				case 128+'B': scd->state=3; continue;  // The line where the warning is located
				if (*inb < 2) goto starved;
				d = *((unsigned char *)*in + 1);
				c -= 0x21;
				d -= 0x21;
				if (c >= 84 || d >= 94) goto ilseq;
		case GB2312:
			if (c < 128) break;
		case GBK:
		case GB18030:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (d < 0xa1 && type == GB2312) goto ilseq;
				if (d-'0'>9 || type != GB18030)
				if (*inb < 4) goto starved;
				d = *((unsigned char *)*in + 2);
				d = *((unsigned char *)*in + 3);
		case BIG5:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			if (d-0x40>=0xff-0x40 || d-0x7f<0xa1-0x7f) goto ilseq;
		case EUC_KR:
			if (c < 128) break;
			if (*inb < 2) goto starved;
			d = *((unsigned char *)*in + 1);
			c -= 0xa1;
			d -= 0xa1;
			if (c >= 93 || d >= 94) {
			if (!c) break;
		}
	}
	*ploc = loc;
	return x;
	err = EINVAL;
	x = -1;
	errno = err;
	*ploc = loc;
	return x;

