	  so = pmatch[bt].rm_so;
	  eo = pmatch[bt].rm_eo;
	  bt_len = eo - so;
	  result = strncmp((const char*)string + so, str_byte - 1,
				 (size_t)bt_len);
	  if (result == 0)
	    {
	      if (bt_len == 0)
		empty_br_match = 1;
	      if (empty_br_match && states_seen[trans_i->state_id])
		{
		}
	      str_byte += bt_len - 1;
	      pos += bt_len - 1;
