static reg_errcode_t
tre_add_tags(tre_mem_t mem, tre_stack_t *stack, tre_ast_node_t *tree,
	     tre_tnfa_t *tnfa)
{
  int first_pass = (mem == NULL || tnfa == NULL);
  regset = xmalloc(sizeof(*regset) * ((tnfa->num_submatches + 1) * 2));  // The line where the warning is located
  if (regset == NULL)
    return REG_ESPACE;
  regset[0] = -1;
