void
recalculate_sizes_now(int now)
{
	RB_FOREACH(s, sessions, &sessions) {
		s->attached = 0;
	}
	TAILQ_FOREACH(c, &clients, entry) {
		s = c->session;
		if (s != NULL && !(c->flags & CLIENT_UNATTACHEDFLAGS))
			s->attached++;
		if (ignore_client_size(c))
			continue;
		if (c->tty.sy <= s->statuslines || (c->flags & CLIENT_CONTROL))  // The line where the warning is located
			c->flags |= CLIENT_STATUSOFF;
		else
			c->flags &= ~CLIENT_STATUSOFF;
	}

static void
input_parse(struct input_ctx *ictx, u_char *buf, size_t len)
{
	const struct input_transition	*itr = NULL;
	size_t				 off = 0;
	while (off < len) {
		ictx->ch = buf[off++];
		if (ictx->state != state ||
		    itr == NULL ||
		    ictx->ch < itr->first ||
		    ictx->ch > itr->last) {
			itr = ictx->state->transitions;  // The line where the warning is located
			while (itr->first != -1 && itr->last != -1) {
				if (ictx->ch >= itr->first &&
				    ictx->ch <= itr->last)
					break;
				itr++;
			}
			if (itr->first == -1 || itr->last == -1) {
				fatalx("no transition from state");
			}
		}
		state = ictx->state;
		if (itr->handler != input_print)
			screen_write_collect_end(sctx);
		if (itr->handler != NULL && itr->handler(ictx) != 0)
			continue;
		if (itr->state != NULL)
			input_set_state(ictx, itr);
		if (ictx->state != &input_state_ground)
			evbuffer_add(ictx->since_ground, &ictx->ch, 1);
	}

static void
server_client_reset_state(struct client *c)
{
	struct tty		*tty = &c->tty;
	struct window_pane	*wp = server_client_get_pane(c), *loop;
	struct screen		*s = NULL;
	u_int			 cx = 0, cy = 0, ox, oy, sx, sy;
	if (c->flags & (CLIENT_CONTROL|CLIENT_SUSPENDED))
		return;
	flags = (tty->flags & TTY_BLOCK);
	tty->flags &= ~TTY_BLOCK;
	if (c->overlay_draw != NULL) {
		if (c->overlay_mode != NULL)
			s = c->overlay_mode(c, c->overlay_data, &cx, &cy);
	} else
		s = wp->screen;
	if (s != NULL)
		mode = s->mode;
	tty_region_off(tty);
	tty_margin_off(tty);
	if (c->prompt_string != NULL) {
	} else if (c->overlay_draw == NULL) {
		tty_window_offset(tty, &ox, &oy, &sx, &sy);
		if (wp->xoff + s->cx >= ox && wp->xoff + s->cx <= ox + sx &&  // The line where the warning is located
		    wp->yoff + s->cy >= oy && wp->yoff + s->cy <= oy + sy) {
			cursor = 1;
			cx = wp->xoff + s->cx - ox;
			cy = wp->yoff + s->cy - oy;
			if (status_at_line(c) == 0)
				cy += status_line_size(c);
		if (!cursor)
			mode &= ~MODE_CURSOR;
	}
	log_debug("%s: cursor to %u,%u", __func__, cx, cy);
	tty_cursor(tty, cx, cy);
	if (options_get_number(oo, "mouse")) {
		if (c->overlay_draw == NULL) {
			mode &= ~ALL_MOUSE_MODES;
			TAILQ_FOREACH(loop, &w->panes, entry) {
				if (loop->screen->mode & MODE_MOUSE_ALL)
					mode |= MODE_MOUSE_ALL;
			}
		}
		if (~mode & MODE_MOUSE_ALL)
			mode |= MODE_MOUSE_BUTTON;
	}
	if (c->overlay_draw == NULL && c->prompt_string != NULL)
		mode &= ~MODE_BRACKETPASTE;
	tty_update_mode(tty, mode, s);

