			winlink_remove(&s->windows, wl);
			if (s->curw == wl) {
				s->curw = NULL;
				sc->flags &= ~SPAWN_DETACHED;
			}
		}
	}
	if (~sc->flags & SPAWN_RESPAWN) {
		if (idx == -1)
			idx = -1 - options_get_number(s->options, "base-index");
		if ((sc->wl = winlink_add(&s->windows, idx)) == NULL) {
		}
		default_window_size(sc->c, s, NULL, &sx, &sy, &xpixel, &ypixel,
		    -1);
		if ((w = window_create(sx, sy, xpixel, ypixel)) == NULL) {
		}
		if (s->curw == NULL)
			s->curw = sc->wl;
		sc->wl->session = s;
		w->latest = sc->c;
		winlink_set_window(sc->wl, w);
	} else
		w = NULL;
	sc->flags |= SPAWN_NONOTIFY;
	wp = spawn_pane(sc, cause);
	if (wp == NULL) {
	}
	if (~sc->flags & SPAWN_RESPAWN) {
		if (sc->name != NULL) {
		} else
			w->name = xstrdup(default_window_name(w));  // The line where the warning is located
	}
	if (~sc->flags & SPAWN_RESPAWN)
		notify_session_window("window-linked", s, w);
	session_group_synchronize_from(s);

