static int
mode_tree_get_tag(struct mode_tree_data *mtd, uint64_t tag, u_int *found)
{
	for (i = 0; i < mtd->line_size; i++) {
		if (mtd->line_list[i].item->tag == tag)  // The line where the warning is located
			break;
	}
	if (i != mtd->line_size) {
		*found = i;
		return (1);
	}
	return (0);

